import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

smooth_l1_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void smooth_l1_kernel(const float* pred, const float* target, float* loss, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float diff = pred[idx] - target[idx];
        float abs_diff = fabsf(diff);
        loss[idx] = (abs_diff < 1.0f) ? 0.5f * diff * diff : abs_diff - 0.5f;
    }
}

torch::Tensor smooth_l1_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    TORCH_CHECK(predictions.is_contiguous(), "Predictions must be contiguous");
    TORCH_CHECK(targets.is_contiguous(), "Targets must be contiguous");
    TORCH_CHECK(predictions.sizes() == targets.sizes(), "Input sizes must match");

    int64_t n = predictions.numel();
    auto loss = torch::empty_like(predictions);

    const int block_size = 256;
    const int num_blocks = (n + block_size - 1) / block_size;

    smooth_l1_kernel<<<num_blocks, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        loss.data_ptr<float>(),
        n
    );

    return torch::mean(loss);
}
"""

smooth_l1_cpp_source = "torch::Tensor smooth_l1_loss_cuda(torch::Tensor predictions, torch::Tensor targets);"

smooth_l1_loss = load_inline(
    name='smooth_l1_loss',
    cpp_sources=smooth_l1_cpp_source,
    cuda_sources=smooth_l1_source,
    functions=['smooth_l1_loss_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, predictions, targets):
        return smooth_l1_loss.smooth_l1_loss_cuda(predictions, targets)
